49	    e.preventDefault();
50	    setErro(null);
51	    setLoading(true);
52	    try {
53	      const { token } = await login(loginKey, password);
54	      setGarcomToken(token);
55	      onLogin();
56	    } catch (err) {
57	      setErro(err.message ?? 'Senha inválida.');
58	    } finally {
59	      setLoading(false);
60	    }
61	  };
62	
63	  return (
64	    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B] flex items-center justify-center p-4">
