72	        </div>
73	        <form onSubmit={handleSubmit} className="space-y-3">
74	          <input
75	            type="password"
76	            value={password}
77	            onChange={(e) => setPassword(e.target.value)}
78	            placeholder="Senha"
79	            autoFocus
80	            required
81	            className="w-full bg-white dark:bg-[#27272A] text-[#18181B] dark:text-[#F4F4F5] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-3 text-sm focus:outline-none focus:border-[#FF441F]"
82	          />
83	          {erro && <p className="text-xs text-red-600 dark:text-red-400">{erro}</p>}
