47	        </div>
48	        <div className="space-y-3 mb-4">
49	          <div>
50	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">
51	              {isSaida ? 'Motivo da retirada *' : 'Descrição *'}
52	            </label>
53	            <input value={descricao} onChange={(e) => setDescricao(e.target.value)}
54	              placeholder={isSaida ? 'Ex: Pagamento fornecedor, troco extra…' : 'Ex: Reforço de troco, fundo extra…'}
55	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
56	          </div>
57	          <div>
58	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Valor (R$) *</label>
59	            <input type="number" min="0.01" step="0.01" value={valor} onChange={(e) => setValor(e.target.value)}
60	              placeholder="0,00"
61	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
62	          </div>
63	          <div>
64	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Meio</label>
65	            <select value={meio} onChange={(e) => setMeio(e.target.value)}
66	              className="mx-2 sm:mx-0 w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]">
67	              <option value="dinheiro">Dinheiro</option>
68	              <option value="pix">PIX</option>
69	              <option value="transferencia">Transferência</option>
70	              <option value="cartao">Cartão</option>
71	            </select>
72	          </div>
73	        </div>
74	        <div className="flex gap-2">
75	          <button onClick={onCancelar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Cancelar</button>
76	          <button
77	            onClick={() => onSalvar({ descricao: descricao.trim(), valor: parseFloat(valor) || 0, meio })}
78	            disabled={salvando || !descricao.trim() || !parseFloat(valor)}
79	            className={`flex-1 py-2.5 text-sm rounded-xl font-bold text-white disabled:opacity-50 ${isSaida ? 'bg-red-500 hover:bg-red-600' : 'bg-green-600 hover:bg-green-700'}`}>
80	            {salvando ? 'Salvando...' : isSaida ? 'Registrar Sangria' : 'Registrar Adição'}
81	          </button>
82	        </div>
83	      </div>
84	    </div>
85	  );
86	};
87	
88	const CaixaAtualPanel = ({ caixa, taxaPagbank, onRefresh, pedidosAbertos = [], restauranteNome }) => {
89	  const [modal, setModal] = useState(null); // 'sangria' | 'adicao' | 'fechar' | null
90	  const [salvando, setSalvando] = useState(false);
91	  const [fechando, setFechando] = useState(false);
92	  const [estornando, setEstornando] = useState(null); // index da saída sendo estornada
93	  const [pendencias, setPendencias] = useState(null); // { pedidos, comandas, mesas, pedidos_em_preparo, itens_em_preparo } vindo do 409 do backend
94	  const [marcandoProntos, setMarcandoProntos] = useState(false);
95	  const [excluindoComandas, setExcluindoComandas] = useState(false);
96	
97	  if (!caixa?.aberto) return null;
98	
99	  const r = caixa.resumo ?? {};
100	  const por = r.por_pagamento ?? {};
101	  // Troco devolvido via Pix (ver troco_via_pix) sai do Pix do estabelecimento — desconta
102	  // do total digital, senão o card mostra dinheiro que já foi embora.
103	  const digitalTotal = Object.entries(por).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v, 0) + (r.pix_calculado ?? 0);
104	  const taxaEst = taxaPagbank > 0 ? digitalTotal * (taxaPagbank / 100) : 0;
105	  const saidas = caixa.saidas ?? [];
106	  const entradas = caixa.entradas ?? [];
107	
108	  const handleMovimento = async (body) => {
109	    setSalvando(true);
110	    try {
111	      const isSaida = modal === 'sangria';
112	      const res = isSaida ? await adicionarSaida(body) : await adicionarEntrada(body);
113	      if (res?.recibo?.via !== 'agente') {
114	        printReciboMovimentoCaixa(isSaida ? 'Sangria' : 'Adição', body, restauranteNome);
115	      }
116	      await onRefresh();
117	      setModal(null);
118	    } catch (e) { alert(e.message); }
119	    finally { setSalvando(false); }
120	  };
121	
122	  const handleEstornar = async (index) => {
123	    if (!confirm('Estornar essa saída? O valor volta a contar no caixa.')) return;
124	    setEstornando(index);
125	    try {
126	      await estornarSaida(index);
127	      await onRefresh();
128	    } catch (e) { alert(e.message); }
129	    finally { setEstornando(null); }
130	  };
131	
132	  const handleMarcarProntos = async ({ pedidoIds = [], itemIds = [] }) => {
133	    setMarcandoProntos(true);
134	    try {
135	      await Promise.all([
136	        ...pedidoIds.map((id) => atualizarStatusPedido(id, 'ready')),
137	        ...itemIds.map((id) => marcarItemProntoRestaurante(id)),
138	      ]);
139	      setPendencias((prev) => prev && {
140	        ...prev,
141	        pedidos_em_preparo: (prev.pedidos_em_preparo ?? []).filter((p) => !pedidoIds.includes(p.id)),
142	        itens_em_preparo: (prev.itens_em_preparo ?? []).filter((i) => !itemIds.includes(i.id)),
143	      });
144	      await onRefresh();
145	    } catch (e) { alert(e.message); }
146	    finally { setMarcandoProntos(false); }
147	  };
148	
149	  const handleExcluirComandas = async (ids) => {
150	    setExcluindoComandas(true);
151	    try {
152	      const resultados = await Promise.allSettled(ids.map((id) => cancelarComandaSalao(id)));
153	      const idsOk = ids.filter((_, i) => resultados[i].status === 'fulfilled');
154	      const falhas = resultados.filter((r) => r.status === 'rejected');
155	      setPendencias((prev) => {
156	        if (!prev) return prev;
157	        const mesaIdsLiberados = (prev.comandas ?? [])
158	          .filter((c) => idsOk.includes(c.id))
159	          .map((c) => c.mesa_id)
160	          .filter(Boolean);
161	        return {
162	          ...prev,
163	          comandas: (prev.comandas ?? []).filter((c) => !idsOk.includes(c.id)),
164	          mesas: (prev.mesas ?? []).filter((m) => !mesaIdsLiberados.includes(m.id)),
165	        };
166	      });
167	      await onRefresh();
168	      if (falhas.length) alert(`${falhas.length} comanda(s) não puderam ser excluídas: ${falhas.map((f) => f.reason?.message ?? 'erro desconhecido').join(', ')}`);
169	    } finally { setExcluindoComandas(false); }
170	  };
171	
172	  const handleFechar = async (body) => {
173	    setFechando(true);
174	    try {
175	      await fecharCaixa(body);
176	      await onRefresh();
177	      setModal(null);
178	      setPendencias(null);
179	    } catch (e) {
180	      if (e.data?.pedidos || e.data?.comandas || e.data?.mesas) {
181	        setPendencias({
182	          pedidos: e.data.pedidos ?? [], comandas: e.data.comandas ?? [], mesas: e.data.mesas ?? [],
183	          pedidos_em_preparo: e.data.pedidos_em_preparo ?? [], itens_em_preparo: e.data.itens_em_preparo ?? [],
184	        });
185	      } else {
186	        alert(e.message);
187	      }
188	    }
189	    finally { setFechando(false); }
190	  };
191	
192	  return (
193	    <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-5">
194	      {/* Header */}
195	      <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
196	        <div>
197	          <div className="flex items-center gap-2">
198	            <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
199	            <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">Caixa em Operação</p>
200	          </div>
201	          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">
202	            {caixa.nome_operador} · aberto às {fmtHora(caixa.aberto_em)} · fundo: {fmt(caixa.valor_inicial)}
203	          </p>
204	        </div>
205	        <div className="flex flex-wrap gap-2">
206	          <button onClick={() => setModal('sangria')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-50 dark:hover:bg-red-950/40">
207	            <Icon name="ArrowDownLeft" size={13} /> Sangria
208	          </button>
209	          <button onClick={() => setModal('adicao')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 rounded-xl hover:bg-green-50 dark:hover:bg-green-950/40">
210	            <Icon name="ArrowUpRight" size={13} /> Adição
211	          </button>
212	          <button onClick={() => { setPendencias(null); setModal('fechar'); }} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-red-500 text-white rounded-xl hover:bg-red-600">
213	            <Icon name="Lock" size={13} /> Fechar Caixa
214	          </button>
215	        </div>
216	      </div>
217	
218	      {/* KPIs principais */}
219	      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-3">
220	        <Kpi icon="Banknote"   label="Espécie no caixa" value={fmt(r.especie_calculada)} color="green" sub="Dinheiro físico esperado" />
221	        <Kpi icon="Smartphone" label="Digital (PagBank)" value={fmt(digitalTotal)} color="blue"
222	          sub={taxaEst > 0 ? `Taxa est.: ${fmt(taxaEst)}` : 'Sem taxa configurada'} />
223	        <Kpi icon="TrendingUp" label="Total Vendas" value={fmt(r.total_vendas)} color="gray" sub={`${r.entregues ?? 0} pedidos entregues`} />
224	      </div>
225	
226	      {/* KPIs secundários */}
227	      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
228	        <Kpi icon="Wallet"       label="Fundo Inicial (Troco)" value={fmt(caixa.valor_inicial)} color="gray" />
229	        <Kpi icon="ArrowUpRight" label="Adições"               value={fmt(r.total_entradas)}   color="green" sub={`${entradas.length} registros`} />
230	        <Kpi icon="ArrowDownLeft" label="Sangrias / Saídas"    value={fmt(r.total_saidas)}     color="red"   sub={`${saidas.length} registros`} />
231	      </div>
232	
233	      {/* Vendas por método — cash/pix aqui mostram o caixa de fato (valor recebido do
234	          cliente / líquido de troco via Pix), não o valor da venda. */}
235	      {Object.keys(por).length > 0 && (
236	        <div className="bg-[#FAFAFA] dark:bg-[#18181B] rounded-xl p-3 mb-3">
237	          <p className="text-xs font-black text-[#A1A1AA] uppercase tracking-widest mb-2">Vendas por método de pagamento</p>
238	          <div className="flex flex-wrap gap-4">
239	            {Object.entries(por).map(([k, v]) => {
240	              // Troco físico já deixa o valor da venda correto sozinho (cliente devolveu em
241	              // dinheiro) — só troco via Pix precisa desse ajuste (fica no caixa em espécie,
242	              // mas sai do Pix).
243	              const valorExibido = k === 'cash' ? v - (r.pix_calculado ?? 0)
244	                : k === 'pix' ? v + (r.pix_calculado ?? 0)
245	                : v;
246	              return (
247	                <div key={k} className="text-base">
248	                  <span className="text-[#71717A] dark:text-[#A1A1AA] font-medium">{k === 'pix' ? 'Saldo Pix' : (PL[k] ?? k)}: </span>
249	                  <span className="font-bold text-lg text-[#18181B] dark:text-[#F4F4F5]">{fmt(valorExibido)}</span>
250	                  {k === 'pix' && (r.pix_calculado ?? 0) !== 0 && (
251	                    <span className="text-sm text-[#71717A] dark:text-[#A1A1AA]"> (recebido: {fmt(v)})</span>
252	                  )}
253	                </div>
254	              );
255	            })}
256	          </div>
257	          {taxaEst > 0 && (
258	            <div className="mt-2 pt-2 border-t border-[#E4E4E7] dark:border-[#3F3F46] flex justify-between text-xs">
259	              <span className="text-[#71717A] dark:text-[#A1A1AA]">Estimativa desconto PagBank ({taxaPagbank}%)</span>
260	              <span className="font-bold text-red-500 dark:text-red-400">- {fmt(taxaEst)}</span>
261	            </div>
262	          )}
263	        </div>
264	      )}
265	
266	      {/* Movimentos recentes */}
267	      {(saidas.length > 0 || entradas.length > 0) && (
268	        <div className="grid sm:grid-cols-2 gap-3">
269	          {saidas.length > 0 && (
270	            <div className="min-w-0">
271	              <p className="text-[10px] font-black text-red-500 dark:text-red-400 uppercase tracking-widest mb-1">Sangrias / Saídas</p>
272	              <div className="space-y-1 max-h-28 overflow-y-auto overflow-x-auto">
273	                {[...saidas].reverse().map((s, i) => {
274	                  const idx = saidas.length - 1 - i;
275	                  return (
276	                    <div key={idx} className="flex justify-between items-center text-xs bg-red-50 dark:bg-red-950/40 rounded-lg px-2.5 py-1.5">
277	                      <span className="flex items-center gap-1 mr-2 flex-1 min-w-0">
278	                        <span className="text-[#71717A] dark:text-[#A1A1AA] truncate">{MEIO_LABELS[s.meio] ?? '💵'} {s.descricao}</span>
279	                        {s.tipo && (
280	                          <span className="text-[9px] px-1.5 py-0.5 rounded-full font-bold bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400 flex-shrink-0">
281	                            {s.tipo === 'troco' ? 'Troco' : s.tipo === 'gorjeta' ? 'Gorjeta' : s.tipo}
282	                          </span>
283	                        )}
284	                      </span>
285	                      <span className="flex items-center gap-1.5 flex-shrink-0">
286	                        <span className="font-bold text-red-600 dark:text-red-400">- {fmt(s.valor)}</span>
287	                        <button
288	                          onClick={() => handleEstornar(idx)}
289	                          disabled={estornando === idx}
290	                          title="Retornar ao caixa"
291	                          className="text-[9px] font-bold px-1.5 py-0.5 rounded-full border border-red-200 dark:border-red-800 text-red-500 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-950/40 disabled:opacity-50">
292	                          {estornando === idx ? '...' : 'Retornar'}
293	                        </button>
294	                      </span>
295	                    </div>
296	                  );
297	                })}
298	              </div>
299	            </div>
300	          )}
301	          {entradas.length > 0 && (
302	            <div className="min-w-0">
303	              <p className="text-[10px] font-black text-green-600 dark:text-green-400 uppercase tracking-widest mb-1">Adições</p>
304	              <div className="space-y-1 max-h-28 overflow-y-auto overflow-x-auto">
305	                {[...entradas].reverse().map((e, i) => (
306	                  <div key={i} className="flex justify-between items-center text-xs bg-green-50 dark:bg-green-950/40 rounded-lg px-2.5 py-1.5">
307	                    <span className="text-[#71717A] dark:text-[#A1A1AA] truncate mr-2 flex-1 min-w-0">{MEIO_LABELS[e.meio] ?? '💵'} {e.descricao}</span>
308	                    <span className="font-bold text-green-700 dark:text-green-400 flex-shrink-0">+ {fmt(e.valor)}</span>
309	                  </div>
310	                ))}
311	              </div>
312	            </div>
313	          )}
314	        </div>
315	      )}
316	
317	      {/* Modais */}
318	      {(modal === 'sangria' || modal === 'adicao') && (
319	        <MovimentoModal tipo={modal} onSalvar={handleMovimento} onCancelar={() => setModal(null)} salvando={salvando} />
320	      )}
321	      {modal === 'fechar' && (
322	        <FecharCaixaModal
323	          resumo={caixa.resumo}
324	          aberto_em={caixa.aberto_em}
325	          valorInicial={caixa.valor_inicial}
326	          pedidosAbertos={pendencias?.pedidos ?? pedidosAbertos}
327	          comandasAbertas={pendencias?.comandas ?? []}
328	          mesasAbertas={pendencias?.mesas ?? []}
329	          pedidosEmPreparo={pendencias?.pedidos_em_preparo ?? []}
330	          itensEmPreparo={pendencias?.itens_em_preparo ?? []}
331	          onMarcarProntos={handleMarcarProntos}
332	          marcandoProntos={marcandoProntos}
333	          onExcluirComandas={handleExcluirComandas}
334	          excluindoComandas={excluindoComandas}
335	          onConfirmar={handleFechar}
336	          onFecharETransferir={() => {}}
337	          onCancelar={() => { setPendencias(null); setModal(null); }}
338	          fechando={fechando}
339	        />
340	      )}
341	    </div>
342	  );
343	};
344	
345	export default CaixaAtualPanel;
