import React, { useState } from 'react';
import Icon from '../../components/AppIcon';
import { adicionarSaida, adicionarEntrada, estornarSaida, fecharCaixa, atualizarStatusPedido, marcarItemProntoRestaurante, cancelarComandaSalao } from '../../services/restauranteService';
import FecharCaixaModal from '../restaurante-dashboard/FecharCaixaModal';
import { printReciboMovimentoCaixa } from '../../utils/printComanda';

const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
const fmtHora = (d) => d ? new Date(d).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : '—';
const MEIO_LABELS = { dinheiro: 'Dinheiro', pix: 'PIX', transferencia: 'Transferência', cartao: 'Cartão' };
const PL = { cash: 'Dinheiro', pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito' };

const Kpi = ({ icon, label, value, sub, color = 'gray' }) => {
  const colors = {
    green: 'border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-950/40',
    blue:  'border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/40',
    amber: 'border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/40',
    red:   'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-950/40',
    gray:  'border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#27272A]',
  };
  const txt = { green: 'text-green-700 dark:text-green-400', blue: 'text-blue-700 dark:text-blue-400', amber: 'text-amber-700 dark:text-amber-400', red: 'text-red-600 dark:text-red-400', gray: 'text-[#18181B] dark:text-[#F4F4F5]' };
  return (
    <div className={`rounded-xl border p-3 ${colors[color]}`}>
      <div className="flex items-center gap-1.5 mb-1">
        <Icon name={icon} size={13} className={txt[color]} />
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#71717A] dark:text-[#A1A1AA]">{label}</p>
      </div>
      <p className={`text-xl font-black ${txt[color]}`}>{value}</p>
      {sub && <p className="text-[10px] text-[#71717A] dark:text-[#A1A1AA] mt-0.5">{sub}</p>}
    </div>
  );
};

// Modal de sangria ou adição
const MovimentoModal = ({ tipo, onSalvar, onCancelar, salvando }) => {
  const [descricao, setDescricao] = useState('');
  const [valor, setValor] = useState('');
  const [meio, setMeio] = useState('dinheiro');
  const isSaida = tipo === 'sangria';

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-[#27272A] rounded-2xl p-6 w-full max-w-sm shadow-2xl">
        <div className="text-center mb-4">
          <p className="text-2xl mb-1">{isSaida ? '💸' : '💰'}</p>
          <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">{isSaida ? 'Sangria (Retirada)' : 'Adição de Dinheiro'}</h2>
          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">{isSaida ? 'Retirada de dinheiro do caixa com motivo' : 'Entrada de dinheiro no caixa'}</p>
        </div>
        <div className="space-y-3 mb-4">
          <div>
            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">
              {isSaida ? 'Motivo da retirada *' : 'Descrição *'}
            </label>
            <input value={descricao} onChange={(e) => setDescricao(e.target.value)}
              placeholder={isSaida ? 'Ex: Pagamento fornecedor, troco extra…' : 'Ex: Reforço de troco, fundo extra…'}
              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Valor (R$) *</label>
            <input type="number" min="0.01" step="0.01" value={valor} onChange={(e) => setValor(e.target.value)}
              placeholder="0,00"
              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Meio</label>
            <select value={meio} onChange={(e) => setMeio(e.target.value)}
              className="mx-2 sm:mx-0 w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]">
              <option value="dinheiro">Dinheiro</option>
              <option value="pix">PIX</option>
              <option value="transferencia">Transferência</option>
              <option value="cartao">Cartão</option>
            </select>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={onCancelar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Cancelar</button>
          <button
            onClick={() => onSalvar({ descricao: descricao.trim(), valor: parseFloat(valor) || 0, meio })}
            disabled={salvando || !descricao.trim() || !parseFloat(valor)}
            className={`flex-1 py-2.5 text-sm rounded-xl font-bold text-white disabled:opacity-50 ${isSaida ? 'bg-red-500 hover:bg-red-600' : 'bg-green-600 hover:bg-green-700'}`}>
            {salvando ? 'Salvando...' : isSaida ? 'Registrar Sangria' : 'Registrar Adição'}
          </button>
        </div>
      </div>
    </div>
  );
};

const CaixaAtualPanel = ({ caixa, taxaPagbank, onRefresh, pedidosAbertos = [], restauranteNome }) => {
  const [modal, setModal] = useState(null); // 'sangria' | 'adicao' | 'fechar' | null
  const [salvando, setSalvando] = useState(false);
  const [fechando, setFechando] = useState(false);
  const [estornando, setEstornando] = useState(null); // index da saída sendo estornada
  const [pendencias, setPendencias] = useState(null); // { pedidos, comandas, mesas, pedidos_em_preparo, itens_em_preparo } vindo do 409 do backend
  const [marcandoProntos, setMarcandoProntos] = useState(false);
  const [excluindoComandas, setExcluindoComandas] = useState(false);

  if (!caixa?.aberto) return null;

  const r = caixa.resumo ?? {};
  const por = r.por_pagamento ?? {};
  // Troco devolvido via Pix (ver troco_via_pix) sai do Pix do estabelecimento — desconta
  // do total digital, senão o card mostra dinheiro que já foi embora.
  const digitalTotal = Object.entries(por).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v, 0) + (r.pix_calculado ?? 0);
  const taxaEst = taxaPagbank > 0 ? digitalTotal * (taxaPagbank / 100) : 0;
  const saidas = caixa.saidas ?? [];
  const entradas = caixa.entradas ?? [];

  const handleMovimento = async (body) => {
    setSalvando(true);
    try {
      const isSaida = modal === 'sangria';
      const res = isSaida ? await adicionarSaida(body) : await adicionarEntrada(body);
      if (res?.recibo?.via !== 'agente') {
        printReciboMovimentoCaixa(isSaida ? 'Sangria' : 'Adição', body, restauranteNome);
      }
      await onRefresh();
      setModal(null);
    } catch (e) { alert(e.message); }
    finally { setSalvando(false); }
  };

  const handleEstornar = async (index) => {
    if (!confirm('Estornar essa saída? O valor volta a contar no caixa.')) return;
    setEstornando(index);
    try {
      await estornarSaida(index);
      await onRefresh();
    } catch (e) { alert(e.message); }
    finally { setEstornando(null); }
  };

  const handleMarcarProntos = async ({ pedidoIds = [], itemIds = [] }) => {
    setMarcandoProntos(true);
    try {
      await Promise.all([
        ...pedidoIds.map((id) => atualizarStatusPedido(id, 'ready')),
        ...itemIds.map((id) => marcarItemProntoRestaurante(id)),
      ]);
      setPendencias((prev) => prev && {
        ...prev,
        pedidos_em_preparo: (prev.pedidos_em_preparo ?? []).filter((p) => !pedidoIds.includes(p.id)),
        itens_em_preparo: (prev.itens_em_preparo ?? []).filter((i) => !itemIds.includes(i.id)),
      });
      await onRefresh();
    } catch (e) { alert(e.message); }
    finally { setMarcandoProntos(false); }
  };

  const handleExcluirComandas = async (ids) => {
    setExcluindoComandas(true);
    try {
      const resultados = await Promise.allSettled(ids.map((id) => cancelarComandaSalao(id)));
      const idsOk = ids.filter((_, i) => resultados[i].status === 'fulfilled');
      const falhas = resultados.filter((r) => r.status === 'rejected');
      setPendencias((prev) => {
        if (!prev) return prev;
        const mesaIdsLiberados = (prev.comandas ?? [])
          .filter((c) => idsOk.includes(c.id))
          .map((c) => c.mesa_id)
          .filter(Boolean);
        return {
          ...prev,
          comandas: (prev.comandas ?? []).filter((c) => !idsOk.includes(c.id)),
          mesas: (prev.mesas ?? []).filter((m) => !mesaIdsLiberados.includes(m.id)),
        };
      });
      await onRefresh();
      if (falhas.length) alert(`${falhas.length} comanda(s) não puderam ser excluídas: ${falhas.map((f) => f.reason?.message ?? 'erro desconhecido').join(', ')}`);
    } finally { setExcluindoComandas(false); }
  };

  const handleFechar = async (body) => {
    setFechando(true);
    try {
      await fecharCaixa(body);
      await onRefresh();
      setModal(null);
      setPendencias(null);
    } catch (e) {
      if (e.data?.pedidos || e.data?.comandas || e.data?.mesas) {
        setPendencias({
          pedidos: e.data.pedidos ?? [], comandas: e.data.comandas ?? [], mesas: e.data.mesas ?? [],
          pedidos_em_preparo: e.data.pedidos_em_preparo ?? [], itens_em_preparo: e.data.itens_em_preparo ?? [],
        });
      } else {
        alert(e.message);
      }
    }
    finally { setFechando(false); }
  };

  return (
    <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-5">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
        <div>
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">Caixa em Operação</p>
          </div>
          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">
            {caixa.nome_operador} · aberto às {fmtHora(caixa.aberto_em)} · fundo: {fmt(caixa.valor_inicial)}
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <button onClick={() => setModal('sangria')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-50 dark:hover:bg-red-950/40">
            <Icon name="ArrowDownLeft" size={13} /> Sangria
          </button>
          <button onClick={() => setModal('adicao')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 rounded-xl hover:bg-green-50 dark:hover:bg-green-950/40">
            <Icon name="ArrowUpRight" size={13} /> Adição
          </button>
          <button onClick={() => { setPendencias(null); setModal('fechar'); }} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-red-500 text-white rounded-xl hover:bg-red-600">
            <Icon name="Lock" size={13} /> Fechar Caixa
          </button>
        </div>
      </div>

      {/* KPIs principais */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-3">
        <Kpi icon="Banknote"   label="Espécie no caixa" value={fmt(r.especie_calculada)} color="green" sub="Dinheiro físico esperado" />
        <Kpi icon="Smartphone" label="Digital (PagBank)" value={fmt(digitalTotal)} color="blue"
          sub={taxaEst > 0 ? `Taxa est.: ${fmt(taxaEst)}` : 'Sem taxa configurada'} />
        <Kpi icon="TrendingUp" label="Total Vendas" value={fmt(r.total_vendas)} color="gray" sub={`${r.entregues ?? 0} pedidos entregues`} />
      </div>

      {/* KPIs secundários */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
        <Kpi icon="Wallet"       label="Fundo Inicial (Troco)" value={fmt(caixa.valor_inicial)} color="gray" />
        <Kpi icon="ArrowUpRight" label="Adições"               value={fmt(r.total_entradas)}   color="green" sub={`${entradas.length} registros`} />
        <Kpi icon="ArrowDownLeft" label="Sangrias / Saídas"    value={fmt(r.total_saidas)}     color="red"   sub={`${saidas.length} registros`} />
      </div>

      {/* Vendas por método — cash/pix aqui mostram o caixa de fato (valor recebido do
          cliente / líquido de troco via Pix), não o valor da venda. */}
      {Object.keys(por).length > 0 && (
        <div className="bg-[#FAFAFA] dark:bg-[#18181B] rounded-xl p-3 mb-3">
          <p className="text-xs font-black text-[#A1A1AA] uppercase tracking-widest mb-2">Vendas por método de pagamento</p>
          <div className="flex flex-wrap gap-4">
            {Object.entries(por).map(([k, v]) => {
              // Troco físico já deixa o valor da venda correto sozinho (cliente devolveu em
              // dinheiro) — só troco via Pix precisa desse ajuste (fica no caixa em espécie,
              // mas sai do Pix).
              const valorExibido = k === 'cash' ? v - (r.pix_calculado ?? 0)
                : k === 'pix' ? v + (r.pix_calculado ?? 0)
                : v;
              return (
                <div key={k} className="text-base">
                  <span className="text-[#71717A] dark:text-[#A1A1AA] font-medium">{k === 'pix' ? 'Saldo Pix' : (PL[k] ?? k)}: </span>
                  <span className="font-bold text-lg text-[#18181B] dark:text-[#F4F4F5]">{fmt(valorExibido)}</span>
                  {k === 'pix' && (r.pix_calculado ?? 0) !== 0 && (
                    <span className="text-sm text-[#71717A] dark:text-[#A1A1AA]"> (recebido: {fmt(v)})</span>
                  )}
                </div>
              );
            })}
          </div>
          {taxaEst > 0 && (
            <div className="mt-2 pt-2 border-t border-[#E4E4E7] dark:border-[#3F3F46] flex justify-between text-xs">
              <span className="text-[#71717A] dark:text-[#A1A1AA]">Estimativa desconto PagBank ({taxaPagbank}%)</span>
              <span className="font-bold text-red-500 dark:text-red-400">- {fmt(taxaEst)}</span>
            </div>
          )}
        </div>
      )}

      {/* Movimentos recentes */}
      {(saidas.length > 0 || entradas.length > 0) && (
        <div className="grid sm:grid-cols-2 gap-3">
          {saidas.length > 0 && (
            <div className="min-w-0">
              <p className="text-[10px] font-black text-red-500 dark:text-red-400 uppercase tracking-widest mb-1">Sangrias / Saídas</p>
              <div className="space-y-1 max-h-28 overflow-y-auto overflow-x-auto">
                {[...saidas].reverse().map((s, i) => {
                  const idx = saidas.length - 1 - i;
                  return (
                    <div key={idx} className="flex justify-between items-center text-xs bg-red-50 dark:bg-red-950/40 rounded-lg px-2.5 py-1.5">
                      <span className="flex items-center gap-1 mr-2 flex-1 min-w-0">
                        <span className="text-[#71717A] dark:text-[#A1A1AA] truncate">{MEIO_LABELS[s.meio] ?? '💵'} {s.descricao}</span>
                        {s.tipo && (
                          <span className="text-[9px] px-1.5 py-0.5 rounded-full font-bold bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400 flex-shrink-0">
                            {s.tipo === 'troco' ? 'Troco' : s.tipo === 'gorjeta' ? 'Gorjeta' : s.tipo}
                          </span>
                        )}
                      </span>
                      <span className="flex items-center gap-1.5 flex-shrink-0">
                        <span className="font-bold text-red-600 dark:text-red-400">- {fmt(s.valor)}</span>
                        <button
                          onClick={() => handleEstornar(idx)}
                          disabled={estornando === idx}
                          title="Retornar ao caixa"
                          className="text-[9px] font-bold px-1.5 py-0.5 rounded-full border border-red-200 dark:border-red-800 text-red-500 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-950/40 disabled:opacity-50">
                          {estornando === idx ? '...' : 'Retornar'}
                        </button>
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
          {entradas.length > 0 && (
            <div className="min-w-0">
              <p className="text-[10px] font-black text-green-600 dark:text-green-400 uppercase tracking-widest mb-1">Adições</p>
              <div className="space-y-1 max-h-28 overflow-y-auto overflow-x-auto">
                {[...entradas].reverse().map((e, i) => (
                  <div key={i} className="flex justify-between items-center text-xs bg-green-50 dark:bg-green-950/40 rounded-lg px-2.5 py-1.5">
                    <span className="text-[#71717A] dark:text-[#A1A1AA] truncate mr-2 flex-1 min-w-0">{MEIO_LABELS[e.meio] ?? '💵'} {e.descricao}</span>
                    <span className="font-bold text-green-700 dark:text-green-400 flex-shrink-0">+ {fmt(e.valor)}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Modais */}
      {(modal === 'sangria' || modal === 'adicao') && (
        <MovimentoModal tipo={modal} onSalvar={handleMovimento} onCancelar={() => setModal(null)} salvando={salvando} />
      )}
      {modal === 'fechar' && (
        <FecharCaixaModal
          resumo={caixa.resumo}
          aberto_em={caixa.aberto_em}
          valorInicial={caixa.valor_inicial}
          pedidosAbertos={pendencias?.pedidos ?? pedidosAbertos}
          comandasAbertas={pendencias?.comandas ?? []}
          mesasAbertas={pendencias?.mesas ?? []}
          pedidosEmPreparo={pendencias?.pedidos_em_preparo ?? []}
          itensEmPreparo={pendencias?.itens_em_preparo ?? []}
          onMarcarProntos={handleMarcarProntos}
          marcandoProntos={marcandoProntos}
          onExcluirComandas={handleExcluirComandas}
          excluindoComandas={excluindoComandas}
          onConfirmar={handleFechar}
          onFecharETransferir={() => {}}
          onCancelar={() => { setPendencias(null); setModal(null); }}
          fechando={fechando}
        />
      )}
    </div>
  );
};

export default CaixaAtualPanel;

