import React, { useState, useMemo } from 'react';
import { getCaixaDetalhe } from '../../services/restauranteService';
import Icon from '../../components/AppIcon';

const fmt    = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
const fmtDt  = (d) => d ? new Date(d).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const isoDay = (d) => new Date(d).toISOString().slice(0, 10);
const isoMon = (d) => new Date(d).toISOString().slice(0, 7);
const today     = () => new Date().toISOString().slice(0, 10);
const thisMonth = () => new Date().toISOString().slice(0, 7);

const STATUS_BADGE  = { aberto: 'bg-green-100 dark:bg-green-950/40 text-green-700 dark:text-green-400 border border-green-200 dark:border-green-800', fechado: 'bg-gray-100 dark:bg-gray-950/40 text-gray-600 dark:text-gray-400 border border-gray-200 dark:border-gray-800', expirado: 'bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400 border border-red-200 dark:border-red-800' };
const STATUS_BORDER = { aberto: 'border-l-green-400', fechado: 'border-l-gray-300', expirado: 'border-l-red-400' };
const STATUS_LABEL  = { aberto: 'Aberto', fechado: 'Fechado', expirado: 'Expirado' };
const MEIO_LABELS   = { dinheiro: '💵', pix: '🏦', transferencia: '🔀', cartao: '💳' };

const KpiCard = ({ icon, label, value, accent }) => (
  <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] px-5 py-4 flex items-center gap-4">
    <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${accent ? 'bg-[#FF441F]/10' : 'bg-[#F4F4F5] dark:bg-[#3F3F46]'}`}>
      <Icon name={icon} size={18} className={accent ? 'text-[#FF441F]' : 'text-[#71717A] dark:text-[#A1A1AA]'} />
    </div>
    <div className="min-w-0">
      <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] font-medium truncate">{label}</p>
      <p className={`text-lg font-black truncate ${accent ? 'text-[#FF441F]' : 'text-[#18181B] dark:text-[#F4F4F5]'}`}>{value}</p>
    </div>
  </div>
);

const Row = ({ label, value, bold, accent }) => (
  <div className={`flex justify-between text-sm py-1.5 border-b border-[#F4F4F5] dark:border-[#3F3F46] last:border-0 ${bold ? 'font-bold' : ''}`}>
    <span className="text-[#71717A] dark:text-[#A1A1AA]">{label}</span>
    <span className={accent ? 'text-[#FF441F] font-bold' : 'text-[#18181B] dark:text-[#F4F4F5]'}>{value}</span>
  </div>
);

const HistoricoCaixasPanel = ({ historico = [] }) => {
  const [expandido,      setExpandido]      = useState(null);
  const [detalhe,        setDetalhe]        = useState({});
  const [loadingDetalhe, setLoadingDetalhe] = useState(null);

  const [busca,  setBusca]  = useState('');
  const [status, setStatus] = useState('todos');
  const [modoDt, setModoDt] = useState('todos');
  const [mesSel, setMesSel] = useState(thisMonth());
  const [dtIni,  setDtIni]  = useState(today());
  const [dtFim,  setDtFim]  = useState(today());

  const handleExpand = async (id) => {
    if (expandido === id) { setExpandido(null); return; }
    setExpandido(id);
    if (detalhe[id]) return;
    setLoadingDetalhe(id);
    try {
      const d = await getCaixaDetalhe(id);
      setDetalhe((prev) => ({ ...prev, [id]: d }));
    } catch { /* silent */ } finally { setLoadingDetalhe(null); }
  };

  const filtrado = useMemo(() => {
    const now    = new Date();
    const semana = new Date(now); semana.setDate(now.getDate() - 7);
    return historico.filter((c) => {
      if (busca && !c.nome_operador.toLowerCase().includes(busca.toLowerCase())) return false;
      if (status !== 'todos' && c.status !== status) return false;
      const aberto = new Date(c.aberto_em);
      if (modoDt === 'hoje')    return isoDay(aberto) === today();
      if (modoDt === 'semana')  return aberto >= semana;
      if (modoDt === 'mes')     return isoMon(aberto) === thisMonth();
      if (modoDt === 'mes_sel') return isoMon(aberto) === mesSel;
      if (modoDt === 'periodo') return aberto >= new Date(dtIni) && aberto <= new Date(dtFim + 'T23:59:59');
      return true;
    });
  }, [historico, busca, status, modoDt, mesSel, dtIni, dtFim]);

  const kpis = useMemo(() => {
    const perdas = filtrado.reduce((s, c) => { const d = c.destinacao_fechamento?.diferenca ?? 0; return s + (d < 0 ? -d : 0); }, 0);
    const saldo  = filtrado.reduce((s, c) => s + (c.resumo?.saldo ?? 0) + (c.destinacao_fechamento?.diferenca ?? 0), 0);
    return { total: filtrado.length, abertos: filtrado.filter((c) => c.status === 'aberto').length, vendas: filtrado.reduce((s, c) => s + (c.resumo?.total_vendas ?? 0), 0), saldo, perdas };
  }, [filtrado]);

  return (
    <div className="space-y-4">
      {/* Título */}
      <div className="flex items-center justify-between">
        <p className="text-sm font-black text-[#18181B] dark:text-[#F4F4F5] uppercase tracking-widest">Histórico de Caixas</p>
        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{historico.length} sessões</p>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <KpiCard icon="Archive"    label="Caixas"       value={kpis.total} />
        <KpiCard icon="Unlock"     label="Abertos"      value={kpis.abertos} />
        <KpiCard icon="TrendingUp" label="Total Vendas" value={fmt(kpis.vendas)} accent />
        <div className={`bg-white dark:bg-[#27272A] rounded-2xl border px-5 py-4 flex items-center gap-4 ${kpis.perdas > 0 ? 'border-red-200 dark:border-red-800' : 'border-[#E4E4E7] dark:border-[#3F3F46]'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${kpis.perdas > 0 ? 'bg-red-50 dark:bg-red-950/40' : 'bg-[#F4F4F5] dark:bg-[#3F3F46]'}`}>
            <Icon name="Wallet" size={18} className={kpis.perdas > 0 ? 'text-red-500 dark:text-red-400' : 'text-[#71717A] dark:text-[#A1A1AA]'} />
          </div>
          <div className="min-w-0">
            <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] font-medium">Saldo Líquido Real</p>
            <p className={`text-lg font-black truncate ${kpis.perdas > 0 ? 'text-red-600 dark:text-red-400' : 'text-[#18181B] dark:text-[#F4F4F5]'}`}>{fmt(kpis.saldo)}</p>
            {kpis.perdas > 0 && <p className="text-[10px] text-red-500 dark:text-red-400 font-semibold"><Icon name="TrendingDown" size={10} className="inline" /> perdas: {fmt(kpis.perdas)}</p>}
          </div>
        </div>
      </div>

      {/* Filtros */}
      <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 space-y-3">
        <p className="text-xs font-black text-[#A1A1AA] uppercase tracking-widest">Filtros</p>
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">

